window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8e42f31ebea3e255"]={"versions": [{"id": "FIG-8e42f31ebea3e255", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm / Schnittstellenrealisierungs-Diagramm der AUTOSAR Adaptive Platform (AP).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Schnittstellenbeziehung des funktionalen Clusters <em>Identity and Access Management</em> (IAM) innerhalb der Adaptive Platform Core-Architektur (<code>AUTOSAR_EXP_SWArchitecture</code>, Kapitel IAM).</li>\n<li><strong>Funktionale Einordnung:</strong> IAM fungiert im AUTOSAR AP Security-Framework als zentraler <strong>Policy Decision Point (PDP)</strong> gemäß XACML-/RBAC-Architekturmuster. Es evaluiert Zugriffsanfragen auf geschützte Ressourcen (z. B. IPC-/Service-Kommunikation via <code>ara::com</code>, Persistenz, Diagnose) autoritativ gegenüber den Policy Enforcement Points (PEP).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponente:</strong></li>\n<li><code>«aapFunctionalCluster» Identity and Access Management</code>: Der funktionale Cluster der Adaptive Platform, welcher die IAM-Funktionalität kapselt und bereitstellt.</li>\n<li><strong>Schnittstelle:</strong></li>\n<li><code>«aapInternal, aapNativeInterface» PolicyDecisionPoint</code>:</li>\n<li><code>«aapInternal»</code>: Nicht für Standard-Adaptive-Applications (ASW) öffentlich freigegebene Schnittstelle; dient der plattforminternen Interaktion zwischen funktionalen Clustern bzw. Middleware-Infrastruktur.</li>\n<li><code>«aapNativeInterface»</code>: Bindung erfolgt über native C++-APIs / lokale In-Process- bzw. IPC-Bibliotheksaufrufe auf Plattformebene (kein AUTOSAR-Service via Service Oriented Architecture / Skeleton-Proxy-Modell).</li>\n<li><strong>Operation:</strong> <code>+ CheckAccess()</code> – Methode zur Evaluierung von Autorisierungsanfragen.</li>\n<li><strong>Beziehung:</strong></li>\n<li><strong>Interface Realization</strong> (gestrichelte Linie mit geschlossener weißer Pfeilspitze): Der funktionale Cluster <code>Identity and Access Management</code> implementiert und instanziiert die Schnittstelle <code>PolicyDecisionPoint</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obwohl das Diagramm eine statische Architektur realisiert, determiniert es den folgenden Laufzeitablauf:</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Ein Klientprozess (Adaptive Application) fordert Zugriff auf eine geschützte Ressource an (z. B. Methodenaufruf, Field-Set, Event-Abonnement oder Prozessstart).</li>\n<li><strong>Abfangen (PEP):</strong> Der zuständige Policy Enforcement Point (z. B. Binding-Layer von <code>ara::com</code>, Execution Management oder ein lokaler Security-Daemon) fängt die Anfrage ab.</li>\n<li><strong>Entscheidungsanforderung (synchron):</strong> Der PEP ruft nativ <code>CheckAccess()</code> am <code>PolicyDecisionPoint</code> (IAM) auf. Übergabeparameter umfassen typischerweise die Anwendungsidentität (UID/GID, Prozesskontext), die Zielressource (Service-ID, Methoden-ID) sowie die angeforderte Zugriffsart.</li>\n<li><strong>Policy-Auswertung:</strong> IAM gleicht die Anfrage gegen die vorkonfigurierten Zugriffsrechte (Access Policies / Manifest Grants) ab.</li>\n<li><strong>Entscheidung & Durchsetzung:</strong> <code>CheckAccess()</code> liefert das Evaluierungsergebnis (z. B. <code>kGranted</code> oder <code>kDenied</code>) synchron an den PEP zurück. Bei Verweigerung bricht der PEP die Ausführung ab und wirft einen plattformspezifischen Security-/Access-Fehler.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Plattform- / Stack-Entwickler:</strong></li>\n<li><strong>PEP-Integration:</strong> Middleware-Komponenten (<code>ara::com</code>, IPC-Transporttreiber, Persistenzschicht) müssen die native Schnittstelle <code>PolicyDecisionPoint</code> einbinden und zwingend vor Ressourcenfreigabe abfragen.</li>\n<li><strong>Latenzkritikalität:</strong> Da <code>CheckAccess()</code> im synchronen Pfad von Inter-Process-Calls liegt, erfordert die Implementierung hochoptimierte Auswertungsmechanismen (z. B. Lockless Data Structures, lokales PDP/PEP-Decision-Caching).</li>\n<li><strong>Applikations-Entwickler:</strong></li>\n<li><strong>Kein API-Zugriff:</strong> Da mit <code>«aapInternal»</code> annotiert, existiert für Applikationen kein direkter C++-Namespace-Aufruf auf <code>PolicyDecisionPoint</code> bzw. <code>CheckAccess()</code>.</li>\n<li><strong>Manifest-Konfiguration:</strong> Zugriffsrechte müssen statisch in den <em>Execution Manifests</em> und <em>Service Instance Manifests</em> über Zugriffsrechte-Modelle (<code>IamAccessGrant</code>, <code>IamProcessGrant</code>, etc.) modelliert werden; fehlende Grants führen zur Laufzeitunterbindung direkt im PEP via IAM.</li>\n</ul>"}, {"id": "FIG-18ba2840c88e6f17", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm / Schnittstellenrealisierungs-Diagramm der AUTOSAR Adaptive Platform (AP).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Schnittstellenbeziehung des funktionalen Clusters <em>Identity and Access Management</em> (IAM) innerhalb der Adaptive Platform Core-Architektur (<code>AUTOSAR_EXP_SWArchitecture</code>, Kapitel IAM).</li>\n<li><strong>Funktionale Einordnung:</strong> IAM fungiert im AUTOSAR AP Security-Framework als zentraler <strong>Policy Decision Point (PDP)</strong> gemäß XACML-/RBAC-Architekturmuster. Es evaluiert Zugriffsanfragen auf geschützte Ressourcen (z. B. IPC-/Service-Kommunikation via <code>ara::com</code>, Persistenz, Diagnose) autoritativ gegenüber den Policy Enforcement Points (PEP).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponente:</strong></li>\n<li><code>«aapFunctionalCluster» Identity and Access Management</code>: Der funktionale Cluster der Adaptive Platform, welcher die IAM-Funktionalität kapselt und bereitstellt.</li>\n<li><strong>Schnittstelle:</strong></li>\n<li><code>«aapInternal, aapNativeInterface» PolicyDecisionPoint</code>:</li>\n<li><code>«aapInternal»</code>: Nicht für Standard-Adaptive-Applications (ASW) öffentlich freigegebene Schnittstelle; dient der plattforminternen Interaktion zwischen funktionalen Clustern bzw. Middleware-Infrastruktur.</li>\n<li><code>«aapNativeInterface»</code>: Bindung erfolgt über native C++-APIs / lokale In-Process- bzw. IPC-Bibliotheksaufrufe auf Plattformebene (kein AUTOSAR-Service via Service Oriented Architecture / Skeleton-Proxy-Modell).</li>\n<li><strong>Operation:</strong> <code>+ CheckAccess()</code> – Methode zur Evaluierung von Autorisierungsanfragen.</li>\n<li><strong>Beziehung:</strong></li>\n<li><strong>Interface Realization</strong> (gestrichelte Linie mit geschlossener weißer Pfeilspitze): Der funktionale Cluster <code>Identity and Access Management</code> implementiert und instanziiert die Schnittstelle <code>PolicyDecisionPoint</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obwohl das Diagramm eine statische Architektur realisiert, determiniert es den folgenden Laufzeitablauf:</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Ein Klientprozess (Adaptive Application) fordert Zugriff auf eine geschützte Ressource an (z. B. Methodenaufruf, Field-Set, Event-Abonnement oder Prozessstart).</li>\n<li><strong>Abfangen (PEP):</strong> Der zuständige Policy Enforcement Point (z. B. Binding-Layer von <code>ara::com</code>, Execution Management oder ein lokaler Security-Daemon) fängt die Anfrage ab.</li>\n<li><strong>Entscheidungsanforderung (synchron):</strong> Der PEP ruft nativ <code>CheckAccess()</code> am <code>PolicyDecisionPoint</code> (IAM) auf. Übergabeparameter umfassen typischerweise die Anwendungsidentität (UID/GID, Prozesskontext), die Zielressource (Service-ID, Methoden-ID) sowie die angeforderte Zugriffsart.</li>\n<li><strong>Policy-Auswertung:</strong> IAM gleicht die Anfrage gegen die vorkonfigurierten Zugriffsrechte (Access Policies / Manifest Grants) ab.</li>\n<li><strong>Entscheidung & Durchsetzung:</strong> <code>CheckAccess()</code> liefert das Evaluierungsergebnis (z. B. <code>kGranted</code> oder <code>kDenied</code>) synchron an den PEP zurück. Bei Verweigerung bricht der PEP die Ausführung ab und wirft einen plattformspezifischen Security-/Access-Fehler.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Plattform- / Stack-Entwickler:</strong></li>\n<li><strong>PEP-Integration:</strong> Middleware-Komponenten (<code>ara::com</code>, IPC-Transporttreiber, Persistenzschicht) müssen die native Schnittstelle <code>PolicyDecisionPoint</code> einbinden und zwingend vor Ressourcenfreigabe abfragen.</li>\n<li><strong>Latenzkritikalität:</strong> Da <code>CheckAccess()</code> im synchronen Pfad von Inter-Process-Calls liegt, erfordert die Implementierung hochoptimierte Auswertungsmechanismen (z. B. Lockless Data Structures, lokales PDP/PEP-Decision-Caching).</li>\n<li><strong>Applikations-Entwickler:</strong></li>\n<li><strong>Kein API-Zugriff:</strong> Da mit <code>«aapInternal»</code> annotiert, existiert für Applikationen kein direkter C++-Namespace-Aufruf auf <code>PolicyDecisionPoint</code> bzw. <code>CheckAccess()</code>.</li>\n<li><strong>Manifest-Konfiguration:</strong> Zugriffsrechte müssen statisch in den <em>Execution Manifests</em> und <em>Service Instance Manifests</em> über Zugriffsrechte-Modelle (<code>IamAccessGrant</code>, <code>IamProcessGrant</code>, etc.) modelliert werden; fehlende Grants führen zur Laufzeitunterbindung direkt im PEP via IAM.</li>\n</ul>"}], "trans": [{"from": "FIG-8e42f31ebea3e255", "to": "FIG-18ba2840c88e6f17", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
